-- Generated by tools/prepare_story.py from docs/story.md; edit the reviewed script.
return {
    {key="after-01", phase="after", level=1, lines={
        {"mara", "Elena, hold the rope! The ring's all rust, but it kept my skiff, the Marigold, all night."},
        {"elena", "Mara, look at the tide marks: green at my knee, white at my waist. Who measures a quay?"},
        {"adrian", "Water next, please, Elena. I fund wells; I don't dig them."},
    }},
    {key="restore-01", phase="restore", level=1, building="Spring well", lines={
        {"mara", "First bucket! Taste it, Elena. No salt, no rust, no goat."},
        {"elena", "Sweet! And the rope brought up a scrap of harbour chart. Mara, quick, a flash by the cliff!"},
        {"mara", "Let's ask. Two flashes out... and two back! Elena, someone's down there."},
    }},
    {key="after-02", phase="after", level=2, lines={
        {"elena", "Mara, working theory: your lamp hit wet jade and bounced off the cliff. A reflection."},
        {"mara", "A reflection that waits its turn? Your jade has manners, Elena."},
        {"elena", "A breath's delay is distance. Tonight my lamp stays in its sack. If it flashes, I'll eat the theory."},
    }},
    {key="after-03", phase="after", level=3, lines={
        {"elena", "Midnight, lamp in its sack, and two flashes anyway. Mara, I withdraw the reflection."},
        {"mara", "Put it in your notes, Elena: \"Mara was right.\""},
        {"elena", "Noted, in the margin, in pencil. Happy?"},
    }},
    {key="after-04", phase="after", level=4, lines={
        {"tomas", "Mind the third post; it bites. Tomas Reed. I keep this harbour."},
        {"mara", "Keep it? They told us this harbour's been empty for years."},
        {"tomas", "True; the islanders keep to the hill villages. Someone counts the tides. You mended my well."},
    }},
    {key="after-05", phase="after", level=5, lines={
        {"elena", "Mr Reed, a lamp answered Mara from under the cliff. Whose is it?"},
        {"tomas", "Ines and I wired a warning lamp under that far cliff, Elena. The storm cut its cable."},
        {"mara", "No cable, no lamp, Tomas. And it still winked at me twice. Rude."},
    }},
    {key="after-06", phase="after", level=6, lines={
        {"tomas", "Come and see where the cable breaks. I spliced it by lantern, and the rain won."},
        {"elena", "\"Ines and I,\" you said before. Who is Ines?"},
        {"tomas", "She worked it with me. Another time, Elena. First, help me roof my father's cabin."},
    }},
    {key="after-07", phase="after", level=7, lines={
        {"mara", "Tomas, the sawmill path! The roof fell in, but the big saw's still in its frame, rusty and smug."},
        {"tomas", "Mend the workshop and it will cut again, Mara. Then I can build a reel for the cable."},
        {"elena", "Then the workshop comes first, Tomas. Timber is the road to everything else here."},
    }},
    {key="after-08", phase="after", level=8, lines={
        {"elena", "Adrian, you had that radio talking a minute ago. Why is it in pieces?"},
        {"adrian", "Salt in the contacts, Elena. Everything out here dies of salt. Pass the screwdriver."},
        {"mara", "I've watched salt eat a hinge overnight, Adrian. Believable. Almost."},
    }},
    {key="after-09", phase="after", level=9, lines={
        {"elena", "Hands off, Adrian! These carvings are older than your bank."},
        {"adrian", "It leaned on me! What are they, Elena?"},
        {"elena", "A river, a tide, and a figure with a lamp at a shutter. Every watch had a keeper, Adrian."},
    }},
    {key="after-10", phase="after", level=10, lines={
        {"mara", "Elena, the third step is wet, and the stair runs on down under the inlet. Brave enough?"},
        {"elena", "Look at the walls, Mara: marks, one above another. Somebody measured this water for years."},
        {"tomas", "It reaches the far station, Elena, and its tide room, the old vault. The key stays on my belt."},
    }},
    {key="after-11", phase="after", level=11, lines={
        {"mara", "Tomas, the colonnade fell like dominoes! Behind it: planks, dry as bread."},
        {"tomas", "First good timber in years, Mara. Carry it to the workshop; the saw wants oil and time."},
        {"adrian", "Wood! Tomas, at last, something on this island I can put on an invoice."},
    }},
    {key="after-12", phase="after", level=12, lines={
        {"tomas", "Mara, hold this: my first reel, shaped by hand. A drop of lamp oil and it turns."},
        {"mara", "Tomas, it wobbles."},
        {"tomas", "It will wind cable. Loose coils lie round the mooring posts, Mara. Bring them in."},
    }},
    {key="after-13", phase="after", level=13, lines={
        {"elena", "Tomas, from the spire I see a dark square under the far ledge. A shutter?"},
        {"tomas", "The far shutter. Shut since the storm, Elena. It should still be."},
        {"mara", "Then someone forgot to tell it, Tomas."},
    }},
    {key="after-14", phase="after", level=14, lines={
        {"elena", "Tomas, every pillar is a tide table, and every great storm is cut into the stone."},
        {"adrian", "Elena, you're sure it's a table and not decoration? It's rather handsome."},
        {"elena", "Decoration doesn't flood, Adrian. I'm sketching all of it."},
    }},
    {key="after-15", phase="after", level=15, lines={
        {"mara", "Elena, the aqueduct's broken in three places. So is the cable. The same three!"},
        {"elena", "Not coincidence, Mara. The cable ran along the arches, and the storm took both."},
        {"tomas", "Then we wind from the first arch. Watch your feet, both of you."},
    }},
    {key="after-16", phase="after", level=16, lines={
        {"mara", "Elena, the harbour mouth, the far cliff, every wave I've ever sworn at, all from up here!"},
        {"elena", "And the dark shutter. Tomas, anyone down there would see a lamp from this height."},
        {"tomas", "Then we need a camp with a proper watch: lamp oil, a book, someone awake. Help me build it."},
    }},
    {key="restore-16", phase="restore", level=16, building="Expedition camp", lines={
        {"mara", "Tomas, is that your father's watch book? Read me the first page."},
        {"tomas", "Off the cabin shelf, Mara. The roof's on, the saw turns. First page is the keeper's hand."},
        {"keeper", "Whoever keeps this watch: when the tide covers the reef, open the shutter. Show the boats."},
        {"mara", "Tomas, I flashed two from the lamp stand and three came back, with a pause before the third!"},
        {"tomas", "Ines kept the far shutter once, Mara. Nobody has, since the storm."},
        {"elena", "Nobody, Tomas, and yet three flashes. Who should answer?"},
    }, prompt="Who should answer the signal?", choices={
        {id="mara", label="Ask Mara to reply", lines={
            {"mara", "One long flash, so they know we've seen them. Tomas, hold the stand for me."},
            {"tomas", "Steady, Mara. There. Now they know somebody's on watch."},
        }},
        {id="tomas", label="Ask Tomas to reply", lines={
            {"tomas", "One long flash means we are listening, Mara. Let me show you."},
            {"mara", "Here, take my lamp. It sticks if you try to be gentle."},
        }},
    }},
    {key="after-17", phase="after", level=17, lines={
        {"mara", "Elena, one long flash at dusk, and nothing since. Moss has moved into my boots."},
        {"elena", "Before, they always answered the same night, Mara. This silence is a message, too. They're thinking."},
        {"tomas", "Or deciding whether we're friends. I'd wait, too, Elena."},
    }},
    {key="after-18", phase="after", level=18, lines={
        {"elena", "Adrian, two wells side by side: one sweet, one brine. The sea reaches under this ridge."},
        {"adrian", "Delightful. Here's the pump order, Elena, signed. I read the number; the number was charming."},
        {"elena", "The rest of the page exists, Adrian. Someday, you must try it."},
    }},
    {key="after-19", phase="after", level=19, lines={
        {"elena", "Tomas, reflection is long dead. What's left is someone alive, with a lamp, who knows the old code."},
        {"tomas", "Or someone taught by those who did, Elena."},
        {"mara", "Then we'll be good company. Highest step tomorrow, at dusk. Coming, both of you?"},
    }},
    {key="before-20", phase="before", level=20, lines={
        {"mara", "Highest step, dusk, tide over the reef, just as the book says. Elena, mind my lamp: it sticks."},
        {"tomas", "Steady hands, Mara. We want them to know somebody is listening."},
        {"elena", "One long flash, then we wait. Whatever comes, Mara, I'm ready."},
    }},
    {key="after-20", phase="after", level=20, lines={
        {"mara", "Elena, our long flash crossed the gap, and a short one came back!"},
        {"elena", "Mara, mind the gaps between flashes: slow, uneven. That's no wire. That's a hand on a shutter."},
        {"tomas", "Then somebody is standing in that dark room, on the wrong side of the water. How do we reach them?"},
    }},
    {key="before-21", phase="before", level=21, lines={
        {"mara", "Tomas, one long flash from us, a lopsided flash back. That's no relay, that's a wrist."},
        {"elena", "A wrist on a schedule, Mara. Same count every night, never quite on time."},
        {"tomas", "Follow the terrace path to that shutter, Mara. Loose stones everywhere; green arrows hold."},
    }},
    {key="after-21", phase="after", level=21, lines={
        {"elena", "Tomas, the vines along this path are cut clean. Not torn, not rotted. Cut, and recently."},
        {"mara", "A machete, or a very tidy goat, Elena."},
        {"tomas", "The islanders know every track here. Give them a market, Mara, and they'll come back and talk."},
    }},
    {key="restore-21", phase="restore", level=21, building="Jungle market", lines={
        {"marisol", "So you're the lamp people. Auntie Marisol. The quay's work belongs to my people. Agreed?"},
        {"adrian", "In writing, madam, gladly. I adore a signature. And I'll buy every yard of your string."},
        {"elena", "Marisol, the builders found a food bag behind your stall beam, dated last week. Yours?"},
        {"marisol", "My knot, my date. Who bought it is my business, scholar. Ask me better questions."},
    }},
    {key="after-22", phase="after", level=22, lines={
        {"mara", "Elena, whose boots? One pair up the stair, one pair back down. And don't say mine."},
        {"elena", "Not yours, Mara. Short stride, left heel worn, someone smaller. Tomas, do you know that walk?"},
        {"tomas", "No. But a dated lunch and one pair of boots, Elena: somebody means to stay."},
    }},
    {key="after-23", phase="after", level=23, lines={
        {"mara", "I'm fine! The lamp's fine! The moss and I will speak later."},
        {"tomas", "You found the loose slab, Mara. The prints step round it. They knew it was there."},
        {"elena", "Then someone has climbed this stair many times, Tomas."},
    }},
    {key="after-24", phase="after", level=24, lines={
        {"adrian", "Elena, my backers are the Meridian Society. Bankers with an interest in old harbours."},
        {"elena", "Bankers on a dig, Adrian? What do they want?"},
        {"adrian", "Tidy reports, darling. Their man Kessler rings now and then. Excuse me, the ridge has signal."},
    }},
    {key="after-25", phase="after", level=25, lines={
        {"elena", "Tomas, nine replies logged since we landed. All at dusk or dawn, never at noon."},
        {"mara", "A night shift, Elena. I respect that."},
        {"tomas", "Dusk and dawn, when the tide covers the reef. The old order, kept to the letter, Elena."},
    }},
    {key="after-26", phase="after", level=26, lines={
        {"tomas", "Adrian, the quay wall is losing stones. It wants dressed stone, and the quarrymen sell at a post."},
        {"adrian", "A trading post, then! Hand me the terms and a pen, Tomas. I never read, I trust faces."},
        {"marisol", "Elena, take that pen off him. Paper decides my cousins' quay jobs, and he reads none."},
    }},
    {key="after-27", phase="after", level=27, lines={
        {"mara", "Elena, new pattern! Long, short, short. Until now it was one lopsided flash."},
        {"elena", "A mechanism repeats itself, Mara. A person who wants noticing changes the tune."},
        {"tomas", "Then we answer politely, Mara. Whoever it is has waited a long while to be heard."},
    }},
    {key="after-28", phase="after", level=28, lines={
        {"elena", "Marisol, these prints stop at the water. Who buys a week of food from you, and gives no name?"},
        {"marisol", "Now that's a question. One customer, exact coin, and I date every bag so it keeps. No more."},
        {"tomas", "Tides wipe prints, Elena. And nobody swims that gap. Not twice."},
    }},
    {key="after-29", phase="after", level=29, lines={
        {"tomas", "Mara, this lamp bracket was bent flat in the storm. Someone has hammered it straight."},
        {"mara", "Right beside my lamp, and I never saw them? Tomas, that's showing off."},
        {"elena", "Straightened, oiled, the lens wiped clean, Mara. A visitor who tidies. Hm."},
    }},
    {key="after-30", phase="after", level=30, lines={
        {"mara", "Red from the far lamp! Tomas, the reef's under the tide, dead ahead! Hauling the Marigold round!", story.SHOUT},
        {"tomas", "My father's order, Mara, in red glass. Whoever it is keeps it better than I did."},
        {"mara", "Soaked, alive, and in somebody's debt. Elena, I want to say thank you to a face."},
    }},
    {key="after-31", phase="after", level=31, lines={
        {"mara", "Biscuit for breakfast, biscuit for lunch. Tomas, for one warm loaf I'd trade my lamp. Almost."},
        {"elena", "Mill first, Mara. Meanwhile, my notes: dusk and dawn, only when the tide covers the reef."},
        {"tomas", "Hours follow the water, Elena. My father flashed one for each hour of the rise."},
    }},
    {key="after-32", phase="after", level=32, lines={
        {"tomas", "Elena, the wire ran down the stair to the tide room at the far station. I bolted it."},
        {"mara", "Then who gets in to work a shutter, Tomas? High water floods that stair."},
        {"elena", "Someone who crosses at low water, Mara, and waits on the ledge as it rises. How, I can't yet say."},
    }},
    {key="after-33", phase="after", level=33, lines={
        {"elena", "Adrian, theory: the Meridian Society wants treasure, and Kessler's men are scouting ahead of us."},
        {"adrian", "Kessler's men? Dull little man, Elena. He sends lawyers, never anyone who can climb a stair."},
        {"mara", "Scouts who answer my lamp, Adrian? Very polite, for treasure hunters."},
    }},
    {key="after-34", phase="after", level=34, lines={
        {"tomas", "Treasure hunters take, Elena. The brass bell is still on its hook, and the lens whole."},
        {"elena", "Then Kessler's men are struck from the notebook, Tomas."},
        {"mara", "A burglar who tidies up. Elena, I think we have a colleague."},
    }},
    {key="after-35", phase="after", level=35, lines={
        {"mara", "Tomas, I stood there two seconds ago! A stone the size of a stool stands there now."},
        {"tomas", "The quay wall, Mara: a crack has opened behind it, and three stones are down. Which hours are safe?"},
        {"elena", "The old tide clock would tell us, Tomas, if it had a tower, hands and a dial."},
    }},
    {key="after-36", phase="after", level=36, lines={
        {"mara", "Elena, I fished a brass disc out of the moss well. Heavy, green, covered in numbers."},
        {"elena", "Mara, a tide dial, marked for this very harbour! In a tower it would tell us the safe hours."},
        {"tomas", "Then give it a tower, Elena. My father set his whole day by that clock."},
    }},
    {key="restore-36", phase="restore", level=36, building="Tide clock tower", lines={
        {"mara", "Elena, the clock ticks! Which hours can I walk the quay without a stone on my head?"},
        {"elena", "Green hours are safe, Mara; red hours, stay off. Tomas, why does the red band begin there?"},
        {"tomas", "It marks the crack's height, Elena. The crack runs into the quay wall, and the sea comes through it."},
        {"elena", "And the flashes come as the red hours begin, Tomas. Whoever it is keeps the water's hours."},
    }},
    {key="after-37", phase="after", level=37, lines={
        {"mara", "Tomas, we walked the wall's foot in the green hours and found a rope, knotted for climbing."},
        {"elena", "Fresh hemp, new knots, Tomas. Whoever climbs here expects the tide back soon."},
        {"tomas", "It's tied to a ring I set myself, years ago. Trust the loops, Mara. They hold."},
    }},
    {key="after-38", phase="after", level=38, lines={
        {"tomas", "Adrian, the strongroom keeps the old bearings. It stays shut until the plaza is mended."},
        {"adrian", "Then open it yesterday, Tomas! I'm dying to see an old bearing."},
        {"marisol", "Look all you like, Mr Vale. The island's records stay where the island can reach them."},
    }},
    {key="after-39", phase="after", level=39, lines={
        {"elena", "Mara, hand me Adrian's string. This crack's an arm's length wide, so he's useful at last."},
        {"mara", "Hero of the market, Elena! I'll tell him."},
        {"tomas", "It was a finger's width when I shut the tide room, Elena. The spring tides have opened it."},
    }},
    {key="before-40", phase="before", level=40, lines={
        {"elena", "Tomas, the green hours open soon. Help me trace this crack to the end of the wall."},
        {"mara", "And I want to meet whoever tied those knots, Elena. Both, then. Let's walk."},
        {"tomas", "Slowly, Mara. The wall is older than my patience, and in a worse mood."},
    }},
    {key="after-40", phase="after", level=40, lines={
        {"elena", "Mara, Tomas, look: pencil fresh under this stone. \"Wall unsafe. I. R.\" It follows the crack."},
        {"marisol", "My cousins who work this quay pass that wall daily. I'll warn them today: short, polite, right."},
        {"tomas", "I. R. I know that R, Elena. The harbour register will tell us, once the plaza is open."},
    }},
    {key="before-41", phase="before", level=41, lines={
        {"elena", "Tomas, pencil on stone: a warning for the quay, two initials. Someone measured this wall."},
        {"mara", "A stranger with manners, flashing at us from a room the sea floods. Tomas, who is she?"},
        {"tomas", "Every boat signed the harbour register, Mara. Find it, and I'll know that R."},
    }},
    {key="after-41", phase="after", level=41, lines={
        {"mara", "Elena, under the reed hut's floor: a book the size of a door. It smells like a wet goat."},
        {"elena", "The harbour register! Tomas, every boat that ever tied up signed in ink."},
        {"tomas", "It wants a dry table, Elena. Open the plaza and I'll read it to you."},
    }},
    {key="restore-41", phase="restore", level=41, building="Harbour plaza", lines={
        {"tomas", "Elena, page nine, over and over: that R like a fishhook. Ines Reed. My sister."},
        {"mara", "Reed, as in Tomas Reed? As in \"Ines and I wired it\"? You dark horse."},
        {"tomas", "I should have said so, Mara. After the storm, her name got hard to say."},
        {"marisol", "Tomas, my bag buyer is a woman who never gave a name. She asked for quiet. I gave it."},
        {"elena", "Her last entry is the storm night, Marisol, yet the stone's note is this week's. Who is she?"},
    }},
    {key="after-42", phase="after", level=42, lines={
        {"elena", "Tomas, forgive me, but I need the true order of that night."},
        {"tomas", "The wall cracked, so I closed the tide room. Ines left for the plans. That was all."},
        {"mara", "And you stayed to mind the lamp, Tomas. Of course you did."},
    }},
    {key="after-43", phase="after", level=43, lines={
        {"tomas", "Then the storm cut the cable, Elena. I spliced until dawn and I did it alone."},
        {"elena", "And Ines?"},
        {"tomas", "She never came up the cliff road. I kept the arrows painted green and watched it anyway."},
    }},
    {key="after-44", phase="after", level=44, lines={
        {"tomas", "Elena, I've thought it through. Ines must have drowned, and someone is borrowing her initials."},
        {"elena", "It fits what we hold, Tomas. I do not like how neatly it fits."},
        {"mara", "A stranger who signs with her fishhook R? Then let's find a second sample of that hand, Elena."},
    }},
    {key="after-45", phase="after", level=45, lines={
        {"elena", "Tomas, a tide table's chalked inside the vault's stair door, this week's tides ticked in pencil."},
        {"tomas", "Hooked ticks, Elena. I taught that tally to one person. She added the hook to annoy me."},
        {"tomas", "I was wrong, both of you. Nobody borrows a tally. Ines is alive, and she is writing."},
    }},
    {key="after-46", phase="after", level=46, lines={
        {"mara", "Dawn, and the far shutter's still winking, Elena. That woman never sleeps."},
        {"elena", "Whatever papers she left need more than a windy terrace. We need one hall, one table, Adrian."},
        {"adrian", "I volunteer to carry chairs, Elena. I'm told it's the one thing I do well."},
    }},
    {key="restore-46", phase="restore", level=46, building="Harbour lodge", lines={
        {"mara", "Adrian, that's my elbow! One table for the whole crew, and red mullet for twelve."},
        {"tomas", "Elena, Ines's harbour log, dry on the lodge shelf. The crack grows a finger each spring tide."},
        {"elena", "Tomas, page three says \"bypass\", with no drawing, and the last page is torn out. What did she mean?"},
        {"tomas", "I don't know, Elena. Ines never explained a thing until it worked."},
    }},
    {key="after-47", phase="after", level=47, lines={
        {"mara", "Elena, a page stuck in the salt crust on the steps. Same pencil as the tally!"},
        {"elena", "\"Six feet,\" underlined twice, Tomas. \"Plans in the chart cabinet, no.\" Then it tears off."},
        {"tomas", "Six feet from what, Elena? And a cabinet without a number."},
    }},
    {key="after-48", phase="after", level=48, lines={
        {"tomas", "Elena, the stone gauge by the lantern steps. She took every reading there."},
        {"mara", "Tomas, it's under a snarling jaguar and a metre of ferns. It looks pleased to be found."},
        {"elena", "Clear it, both of you. If she measured six feet, she'll have left a mark."},
    }},
    {key="after-49", phase="after", level=49, lines={
        {"elena", "Tomas, there's the six-foot notch, deep as a thumb. And a 7 cut right beside it."},
        {"tomas", "A gauge reads tides, Elena. It has no use for a 7. I never cut that."},
        {"mara", "Then it's her handwriting, in stone. Tomas, what is she counting?"},
    }},
    {key="after-50", phase="after", level=50, lines={
        {"mara", "Elena, rain on the quay, and the crack is spitting water like a cross whale!"},
        {"tomas", "A finger wider than her log says, Mara. We have less time than the book promised."},
        {"elena", "Then we find her plan before the next spring tide, Tomas. Mara, keep the lamp ready."},
    }},
    {key="after-51", phase="after", level=51, lines={
        {"kessler", "Good evening, Mr Vale. I hear a log has turned up. I should like the records."},
        {"adrian", "Terrible line, Kessler! Wind off the sea. I'm losing you. Losing you entirely."},
        {"mara", "The sea is flat as a plate, Adrian."},
    }},
    {key="after-52", phase="after", level=52, lines={
        {"marisol", "Elena, the islanders want somewhere to sit and argue. Is that amphitheatre for us?"},
        {"elena", "For everyone, Marisol. Bring the benches and the arguments."},
        {"tomas", "Marisol, I said Ines's name at the masons' fire tonight. Nothing fell."},
    }},
    {key="after-53", phase="after", level=53, lines={
        {"elena", "Tomas, her log says water pushes at the foot of the wall, never the top. Any ideas?"},
        {"mara", "Give the sea a detour, then. A bypass! A scenic route, Elena. Write it down."},
        {"tomas", "Ines drew circles in the sand when she was thinking. Mara, I never asked what they were."},
    }},
    {key="after-54", phase="after", level=54, lines={
        {"mara", "Tonight's answer came slower, Elena: long, long, short. She never sends the same twice."},
        {"elena", "Then she isn't a fault repeating, Tomas. She's talking, and we're slow to learn the language."},
        {"tomas", "Then I'll learn it. Mara, flash her back slowly. I'm looking, Ines."},
    }},
    {key="after-55", phase="after", level=55, lines={
        {"mara", "Tomas, the far cliff, tide room door, half under water. And a bucket hung on the ledge."},
        {"elena", "Hung out to dry? Someone bails that room by hand, and keeps a routine."},
        {"tomas", "Ines never could abide a wet floor, Elena. That's her bucket."},
    }},
    {key="after-56", phase="after", level=56, lines={
        {"marisol", "Elena, the pearl divers asked me to hand you their reef bearings. They trust water over charts."},
        {"mara", "Tomas, the cartographer's house is being re-roofed. Its drawers are numbered, like her cabinet."},
        {"tomas", "She learned her numbers in that house, Mara. Cabinet, drawer, shelf."},
    }},
    {key="after-57", phase="after", level=57, lines={
        {"mara", "Adrian, why is the radio in forty pieces again?"},
        {"adrian", "It crackled. I'm adjusting the squelch. It's rather like a very small clock."},
        {"elena", "That's the third time since the Mole Walk, Adrian. Who keeps ringing you?"},
    }},
    {key="after-58", phase="after", level=58, lines={
        {"mara", "Tomas, the Gull's bell still hangs on her stump. Who did she carry?"},
        {"tomas", "Pearl divers, Mara, and my father on a good day. Marisol's cousins knew her."},
        {"elena", "Then they may know the reef bearings Ines used. Mara, ask Marisol tomorrow."},
    }},
    {key="after-59", phase="after", level=59, lines={
        {"elena", "Tomas, the gauge shows more than water: a 1, cut above the 7. Whose cutting is that?"},
        {"tomas", "Hers, Elena. One, seven. You hold her page: \"chart cabinet, no.\" The number's torn away."},
        {"mara", "She cut her filing system into the harbour. Cabinet seventeen! Elena, find us the door."},
    }},
    {key="before-60", phase="before", level=60, lines={
        {"elena", "Seventeen, cut where only a keeper would look. Tomas, a cabinet in which building?"},
        {"tomas", "Not the lodge, Elena. The old archive, whose door is behind the Disc of Noon."},
        {"mara", "Then we open the disc first, Tomas, and the archive after."},
    }},
    {key="after-60", phase="after", level=60, lines={
        {"tomas", "Elena, I told myself she wasn't coming back. Somewhere in there I stopped waiting for her."},
        {"mara", "Tomas, she's at that shutter every night, still asking. That's not someone who stopped."},
        {"elena", "Then let's bring her plans into daylight. Cabinet seventeen, in the old archive."},
    }},
    {key="before-61", phase="before", level=61, lines={
        {"elena", "Tomas, her gauge numbers, seven and one, point to cabinet seventeen in the old archive."},
        {"tomas", "My sister is back, Elena. I won't meet her through a locked drawer. Let's dig it out."},
        {"adrian", "Does anyone outside this table know about the cabinet? Purely for safety, of course."},
    }},
    {key="after-61", phase="after", level=61, lines={
        {"mara", "Elena, the reeds are cut back and the archive door shows. It's a lot of door."},
        {"elena", "Damp, Mara, but dry enough inside. Cabinet seventeen may still be in there."},
        {"tomas", "Then the archive gets a roof and a proper lock, Elena. Before anyone else comes looking."},
    }},
    {key="restore-61", phase="restore", level=61, building="Keeper's archive", lines={
        {"elena", "Tomas, the key. The archive stands, and cabinet seventeen is in it."},
        {"tomas", "Off my belt. Ines made both locks, Elena, so one key fits both."},
        {"elena", "It turns! Tomas, a plan with her signature: I. Reed. A bypass at the wall."},
        {"tomas", "She drew where the tide should go instead of into the wall. Elena, she went for this."},
        {"elena", "Open her bypass and the wall can be saved! Adrian, why aren't you cheering?"},
        {"adrian", "Because I must confess something, Elena. I signed our finds over to the Society, through Kessler."},
        {"mara", "Kessler. Adrian, I've wondered since the radio."},
        {"adrian", "It bought the ship, the crew and the cocoa, Mara. It also bought a claim on the records."},
        {"elena", "And Kessler knew about the log, Adrian. You told him."},
        {"adrian", "I did. I thought it harmless. It was not."},
        {"marisol", "Adrian, my cousins work this quay. Their jobs and records, on Kessler's shelf?"},
        {"elena", "Then hear me plainly, Adrian. The plans stay here, and so do the islanders' records."},
    }},
    {key="after-62", phase="after", level=62, lines={
        {"elena", "Adrian, I have moved my notes to the far end of the table. Away from my sponsor."},
        {"adrian", "The table is small, Elena. I can hear you not speaking to me."},
        {"mara", "Cheer up, Adrian. She wrote you down in the margin. In capitals."},
    }},
    {key="after-63", phase="after", level=63, lines={
        {"elena", "Tomas, the archive needs a second key, for Marisol's people. Can you cut one?"},
        {"tomas", "By Ines's pattern, Elena. It will take a week and a file."},
        {"marisol", "Take two weeks, Tomas. A key rushed breaks at the door."},
    }},
    {key="after-64", phase="after", level=64, lines={
        {"tomas", "Elena, the quarry stone has come. Marisol's cousins will lay it to Ines's plan."},
        {"marisol", "My cousin Dario takes the first trowel, Tomas. He starts at dawn, and he's never late."},
        {"elena", "Then the plan says where, Marisol, and Dario says how."},
    }},
    {key="after-65", phase="after", level=65, lines={
        {"elena", "Tomas, the bypass must draw from this well and carry the water off. I'm certain."},
        {"tomas", "Elena, the well is sweet water. Ines's line starts at the tide, below the wall."},
        {"elena", "Then I was wrong, and the well is innocent. Mara, write it down. In capitals."},
    }},
    {key="after-66", phase="after", level=66, lines={
        {"mara", "Tomas, could the old lighthouse guide a boat round the broken quay?"},
        {"tomas", "If its lamp turns again. It sat dark the whole time I kept the harbour."},
        {"elena", "Then light it. Her plan may show us a way ashore."},
    }},
    {key="restore-66", phase="restore", level=66, building="Lighthouse", lines={
        {"mara", "Tomas, stand here and watch that beam sweep the inlet. I want your honest review."},
        {"elena", "Look at her plan first, both of you: a second landing, marked with a cross and a bearing."},
        {"tomas", "Round the point, on the far shore. Ines wanted a way ashore the wall couldn't take."},
        {"elena", "And her plan lists a signal plate for the lamp. Mara, the lantern cradle is empty."},
        {"mara", "Then the beam guides us and the cross is our door. I'll hunt the plate."},
    }},
    {key="after-67", phase="after", level=67, lines={
        {"elena", "Mara, take bearings from the rock. They lead round the broken wall, as she drew them."},
        {"mara", "Elena, the cormorants object. Loudly. One has taken my hat."},
        {"tomas", "That's a sign of good water, Mara. Leave him the hat."},
    }},
    {key="after-68", phase="after", level=68, lines={
        {"adrian", "Elena, I've paid the masons from my own pocket. How else do I make it right?"},
        {"elena", "Do it, and don't ask me to say it. That's how a person makes anything right."},
        {"mara", "Adrian, remember that one. Elena rarely hands out advice for free."},
    }},
    {key="after-69", phase="after", level=69, lines={
        {"tomas", "Elena, that stair is dry only at low water. Not a stone moved. Ines picked well."},
        {"mara", "Tomas, whoever wrecked that ship picked worse. It's lodged in the gate like a cork."},
        {"elena", "Then we go round it, Mara. Mind the slime."},
    }},
    {key="after-70", phase="after", level=70, lines={
        {"elena", "Tomas, low tide at last. The wall is measured, and it matches Ines's mark to the finger."},
        {"tomas", "Six feet of cut, Elena, as she wrote. Her plan was right before we ever read it."},
        {"mara", "Tomas, even the jaguar's mouth is clean. I'd say we've been forgiven."},
    }},
    {key="after-71", phase="after", level=71, lines={
        {"mara", "Tomas, look at that schooner on the beach. Its skiff is rotten, but the keel's good."},
        {"tomas", "A boat could reach that landing at any tide, Mara. Can you mend the skiff?"},
        {"mara", "Give me boards and tar, and the schooner's skiff will carry us there."},
    }},
    {key="after-72", phase="after", level=72, lines={
        {"mara", "Marisol, nets in the loft, dry as the day they were hung. Who saved them?"},
        {"elena", "And who keeps the quay workers' own records? Marisol, I'm asking, not taking."},
        {"marisol", "Ask, and the old netmen talk all night. Take, and the records go quiet. Island rule."},
    }},
    {key="after-73", phase="after", level=73, lines={
        {"tomas", "Mara, I promised her the warning would stay lit. Then the cable broke, and I let it."},
        {"mara", "You didn't let it, Tomas. You rigged a reel from a log."},
        {"tomas", "Late is better than never, Mara. Hand me the lantern."},
    }},
    {key="after-74", phase="after", level=74, lines={
        {"elena", "Mara, from the sea the island is a dark lump. Boats need something tall and distinct."},
        {"mara", "A star observatory? Elena, it isn't up yet."},
        {"elena", "Plans are all we have. I've marked its site on the chart. Tomas, check my bearings."},
    }},
    {key="after-75", phase="after", level=75, lines={
        {"mara", "Tomas, the old stair goes right under the inlet. At full tide it's a swimming bath."},
        {"tomas", "At low tide it's a path to the far station, Mara. Ines uses it. Her chalk is on the fifth step."},
        {"elena", "Smudged, not faded, Tomas. She was here this week."},
    }},
    {key="after-76", phase="after", level=76, lines={
        {"elena", "Mara, the star dome will be the landmark for any boat at dusk. Will the skiff float?"},
        {"mara", "If the tar dries, Elena. It's slow and has opinions."},
        {"elena", "Then bearings first, tar second, Mara. In that order."},
    }},
    {key="after-77", phase="after", level=77, lines={
        {"tomas", "Mara, Ines marked a stone here for the tide. It sits right where the bypass begins."},
        {"mara", "You two did love your marks, Tomas."},
        {"tomas", "She'd have called it good order, Mara. I called it getting in her way."},
    }},
    {key="after-78", phase="after", level=78, lines={
        {"marisol", "Elena, my aunties will dry fish on this terrace again. Tell me the wall will hold."},
        {"elena", "I'll tell you after the bypass runs, Marisol. Not before."},
        {"tomas", "Honest answer, Marisol. Ines never promised what she hadn't measured."},
    }},
    {key="after-79", phase="after", level=79, lines={
        {"mara", "Tomas, the lamp turns smoothly now. May I watch it all night?"},
        {"tomas", "Don't, Mara. Someone must be fresh for the wall."},
        {"elena", "The wall first. Then Ines, with the light behind her."},
    }},
    {key="before-80", phase="before", level=80, lines={
        {"elena", "Tomas, the plan, the second landing, the measured wall. Everything fits but the water."},
        {"tomas", "The foot of the vault stair is where the tide first bites, Elena. We start there."},
        {"adrian", "I'll keep the radio, then. In case someone calls. Someone usually does."},
    }},
    {key="after-80", phase="after", level=80, lines={
        {"kessler", "Mr Vale, I will send a boat for the records in twelve days. Have them ready."},
        {"adrian", "Twelve days. Noted, Kessler. I am reading it carefully."},
        {"elena", "Twelve days, Adrian. We finish Ines's plan first, and the records stay put."},
    }},
    {key="before-81", phase="before", level=81, lines={
        {"elena", "Tomas, Kessler has named his date. Ines's plan is our answer, and the records stay put."},
        {"tomas", "She marked a second landing for us, Elena. She never meant us to fight the quay."},
        {"mara", "Then I'll polish my lamp, Tomas. If she answers, I want a clean flash."},
    }},
    {key="after-81", phase="after", level=81, lines={
        {"marisol", "Tomas, my neighbours are chalking house outlines on the old stones. May they move in?"},
        {"tomas", "Not before the quay has a warning notice, Marisol. Everyone moving in must know the risk."},
        {"elena", "Then the notice goes up first. And your neighbours' names go in my book, not Kessler's."},
    }},
    {key="after-82", phase="after", level=82, lines={
        {"elena", "Marisol, the netmen read their storm notches aloud only to you. Will you sit with me?"},
        {"marisol", "Gladly, Elena. And the archive stays open to the island, or the notches stay in the loft."},
        {"mara", "Elena, bring the lamp. This mist hides the notches, and my feet."},
    }},
    {key="after-83", phase="after", level=83, lines={
        {"elena", "Tomas, the idol's crusted with salt. The sea once reached this terrace. How high?"},
        {"tomas", "The old keepers cut tide marks into its base, Elena. Ines copied them into her log."},
        {"adrian", "I'll pay for a proper survey. Be gentle, Elena. I'm out of practice at generosity."},
    }},
    {key="after-84", phase="after", level=84, lines={
        {"elena", "Nine days to Kessler's boat, Tomas. Which records can we move into the archive today?"},
        {"tomas", "The register and Ines's log, Elena. The rest waits for Marisol's key."},
        {"marisol", "Move nothing at night, Tomas. The island watches what disappears at night."},
    }},
    {key="after-85", phase="after", level=85, lines={
        {"mara", "Elena, that green parrot just said 'Mr Vale' in Kessler's voice! Who taught him?"},
        {"marisol", "He copies what he hears, Mara. Keep your secrets away from that bird."},
        {"tomas", "Then the radio lives indoors, Elena, with the door shut. Tell Adrian."},
    }},
    {key="after-86", phase="after", level=86, lines={
        {"mara", "Tomas, is this Ines's second landing? Deep water, a dry stair, plain as her handwriting."},
        {"tomas", "It is, Mara. Her handwriting, in stone."},
        {"elena", "Marisol, the museum opens to every islander. Our finds stay in it, not in a crate."},
    }},
    {key="after-87", phase="after", level=87, lines={
        {"mara", "Adrian, you've been writing by lantern since supper. What is taking all night?"},
        {"adrian", "One sentence, Mara. It says 'surrender'."},
        {"tomas", "Keep it plain, Adrian. Ines never could stand a long letter."},
    }},
    {key="after-88", phase="after", level=88, lines={
        {"adrian", "Kessler, I surrender the claim. The records stay here."},
        {"kessler", "You will find that expensive, Mr Vale."},
        {"adrian", "Worth every penny. Send the bill to me."},
    }},
    {key="after-89", phase="after", level=89, lines={
        {"tomas", "Mara, my father watched for boats from this tier. I watched for a lamp."},
        {"mara", "And now one answers every night, Tomas."},
        {"tomas", "Then from tonight I answer her flash for flash, Mara. Months of silence are enough."},
    }},
    {key="after-90", phase="after", level=90, lines={
        {"elena", "Tomas, the light below flashes faster, short and sharp. Is she in trouble?"},
        {"tomas", "No, Elena. It's the old tide count, one flash for each hour the water rises."},
        {"mara", "So she's minding our tide from down there. Elena, you can retire the distress theory."},
    }},
    {key="after-91", phase="after", level=91, lines={
        {"mara", "Adrian, that parrot just said \"expensive, Mr Vale\". Whose parrot is this?"},
        {"adrian", "I will not be taking questions about the parrot, Mara."},
        {"tomas", "Elena, the temple is the place for our quay notice. Every worker passes it."},
    }},
    {key="restore-91", phase="restore", level=91, building="Temple of the Sun", lines={
        {"marisol", "Tomas, every quay worker passes this wall at dawn. Read me your notice aloud."},
        {"tomas", "Plain words, Marisol: stay off the foot of the wall at the flood."},
        {"elena", "Tomas, look behind the altar! A bronze plate with a slot: the signal plate Ines's plan lists!"},
        {"mara", "It'll fit my lamp, or I'll make it. Give me a file and a day, Elena."},
    }},
    {key="after-92", phase="after", level=92, lines={
        {"tomas", "Elena, it's the lowest tide of the month. Come, I'm chalking a mark at the foot of the wall."},
        {"elena", "If the bypass works, Tomas, the chalk stays dry at the next flood. If not, it washes out."},
        {"mara", "Tomas, you've got chalk on your ear. The aviary parrots are laying odds."},
    }},
    {key="after-93", phase="after", level=93, lines={
        {"elena", "Tomas, the chart scrap from our first bucket shows Tern Rock Light, and a second lamp beyond."},
        {"tomas", "Another station, Elena. Ines will know who keeps it."},
        {"marisol", "Tomas, my traders left stone, timber and lime at the landing. Pay me in tea."},
    }},
    {key="after-94", phase="after", level=94, lines={
        {"elena", "Tomas, the cistern bell rings when water enters. The keepers could hear the tide."},
        {"tomas", "Ines routed her bypass through it, Elena, then out to the fountain."},
        {"mara", "A wall that tells you when it's working. Tomas, I like her already."},
    }},
    {key="after-95", phase="after", level=95, lines={
        {"mara", "Tomas, a whole mast, beached. Somebody lost an argument with a storm."},
        {"tomas", "It's the best lever on the island, Mara. Ines's plan says: mast moves the sluice stone."},
        {"elena", "Everyone, lift on three, Mara. Not on \"wait\". On three."},
    }},
    {key="after-96", phase="after", level=96, lines={
        {"mara", "Tomas, the stone turned! Water's creeping down the channel toward the cistern."},
        {"tomas", "Slowly, Mara. Ines says open a hand's width and listen for the bell."},
        {"elena", "Then we wait for the cistern bell, Tomas. If it rings, the fountain is next."},
    }},
    {key="restore-96", phase="restore", level=96, building="Jade fountain", lines={
        {"elena", "Tomas, taste it: jade water, straight from Ines's bypass. Where's your chalk mark?"},
        {"tomas", "Dry at the flood and the turn, Elena. And that loop is her sand circle. She drew it first in sand."},
        {"mara", "Then the wall is safe. Now we tell her, Tomas."},
    }},
    {key="after-97", phase="after", level=97, lines={
        {"elena", "Adrian, the cartouche on the fountain reads: no keeper keeps alone. Mark it."},
        {"adrian", "Elena, Kessler's invoice arrived, large and polite. I'm paying it gladly."},
        {"tomas", "Then you've earned a chair at the lodge table, Adrian."},
    }},
    {key="after-98", phase="after", level=98, lines={
        {"adrian", "Marisol, I wrote this myself: the quay jobs and the islanders' records stay with the islanders."},
        {"marisol", "Your own hand, no footnotes? Then sit, Mr Vale. I'll sell you tea at last."},
        {"tomas", "Elena, the lamp is clean and the skiff stocked. Ines will see our lantern from the far cliff."},
    }},
    {key="after-99", phase="after", level=99, lines={
        {"tomas", "Mara, hold the plate steady. I fitted this lamp once with Ines. My hands remember."},
        {"elena", "Tomas, a lantern is moving down the far cliff, step by step. Is that her?"},
        {"mara", "Tomas, my hands are steady. Yours are shaking. Breathe."},
    }},
    {key="before-100", phase="before", level=100, lines={
        {"mara", "Elena, the signal plate's in the lamp. Time for the long flash."},
        {"tomas", "Then I'll take the key down to meet her, Mara."},
        {"elena", "The tide's turning. Go carefully, both of you."},
    }},
    {key="after-100", phase="after", level=100, lines={
        {"mara", "Tomas, long flash out, and three back with a pause before the third. That's her answer!"},
        {"tomas", "Welcome home, Ines. Here's the key. We'll keep the light together."},
        {"ines", "Gladly, Tomas. The quay would have had me, so I came by the far shore and worked the shutter."},
        {"ines", "Mara, I changed its tune till a lamp I could trust answered. And this one did."},
        {"ines", "Elena, your well scrap is a corner of my chart of other lights. They need keepers too."},
    }},
    {key="citizen-man_03", phase="citizen", event="man_03", building="Spring well", lines={
        {"lupe", "Elena, my jars are dry and the hill spring is a two-hour climb. Is this the well that sings?"},
        {"elena", "It sang at us. Who are you, and why come down for water?"},
        {"lupe", "Lupe. I carry for three villages. Fill my jars here, and I'll bring your crew a jar a day."},
    }},
    {key="citizen-man_04", phase="citizen", event="man_04", building="Trapper's cabin", lines={
        {"bastian", "Girl, you've hung your washing on my old snare post. Forty years I've set traps in the hills."},
        {"mara", "Sorry! Is the post yours? I'll move it, if you'll teach me what a trail says."},
        {"bastian", "Bet you can't keep quiet for a mile. Win, and I'll show you how to bring a rock wall down."},
    }},
    {key="citizen-man_02", phase="citizen", event="man_02", building="Carpenter's workshop", lines={
        {"joaquin", "Your bench is crooked, your saw is blunt and the roof leaks. Who built this, Tomas?"},
        {"tomas", "The old keepers. I only oil it. You'd be Joaquín from the upper village?"},
        {"joaquin", "I am. Give me the key and a week, and I'll turn you out boards while you sleep."},
    }},
    {key="citizen-man_01", phase="citizen", event="man_01", building="Expedition camp", lines={
        {"dita", "Mara, that stair behind your camp has sat on its fallen stones for years. May I blow it open?"},
        {"mara", "Blow it? Who sent you, and do you mean a small bang or a loud one?"},
        {"dita", "Nobody sent me. Small, if you hold your ears. I'll bring powder for a second job, too."},
    }},
    {key="citizen-man_05", phase="citizen", event="man_05", building="Jungle market", lines={
        {"marisol", "Fishermen on the left, fruit on the right. And nobody sells in the shade without asking me."},
        {"elena", "Marisol, the hill villages are arriving with baskets. Where do I put the yams?"},
        {"marisol", "Next to the mangoes. If they fight, give them the same ruler and call it fair."},
    }},
    {key="citizen-man_06", phase="citizen", event="man_06", building="Stone trading post", lines={
        {"basile", "Adrian, you stand like a man who has never lifted a block. Is this your quarry?"},
        {"adrian", "Guilty. I only point at things, with great enthusiasm. What would you cut first?"},
        {"basile", "The terrace steps. Point at the next ten and I'll send them down squared and straight."},
    }},
    {key="citizen-man_07", phase="citizen", event="man_07", building="Water mill", lines={
        {"hana", "Mara, your wheel turns, but it grinds nothing. Who taught you to leave a mill empty?"},
        {"mara", "Nobody! We've sacks of rice and tubers in the shed. Will you take them?"},
        {"hana", "Both, and I'll keep a share for flat bread. You'll want to wait at the door, I warn you."},
    }},
    {key="citizen-man_08", phase="citizen", event="man_08", building="Tide clock tower", lines={
        {"ferro", "Elena, your tower keeps tide time but sulks at noon. Mind if I take a look inside?"},
        {"elena", "Please! I've stared at its gears for an hour and they all look guilty."},
        {"ferro", "They are. Hold the ladder, and the tower will chime a warning before the tide turns."},
    }},
    {key="citizen-man_09", phase="citizen", event="man_09", building="Harbour plaza", lines={
        {"nilo", "Tomas, my nets are full in my head and empty in my boat. May I fish off this quay?"},
        {"tomas", "The reef side has rested for years. Who sent you down from the hill landing?"},
        {"nilo", "The tide did. Keep a corner of the plaza clear, and your pots will never be bare."},
    }},
    {key="citizen-man_10", phase="citizen", event="man_10", building="Stone amphitheatre", lines={
        {"zaza", "Adrian, say something from that top row. Hear how the stones throw it back? Beautiful."},
        {"adrian", "Dreadful, I said \"good evening\" and got \"evening\" twice. Can you fill it?"},
        {"zaza", "With a crowd, if I drum loud enough. And a crowd drops coins in a cup."},
    }},
    {key="citizen-man_11", phase="citizen", event="man_11", building="Cartographer's house", lines={
        {"ruth", "Elena, you've pinned my map upside down. Is this what you call a survey?"},
        {"elena", "It's upside down? Then will you set it right and read the old lines for us?"},
        {"ruth", "Ink and an hour. I'll mark where the storm will strike before it comes."},
    }},
    {key="citizen-man_12", phase="citizen", event="man_12", building="Lighthouse", lines={
        {"ulla", "Mara, forty years on deck and I never once saw this lamp lit. Who keeps it?"},
        {"mara", "Nobody, Captain. Will you teach me to read a coast at night?"},
        {"ulla", "Hand me the lens cloth. I'll show you which dark patches are rocks, before you hit them."},
    }},
    {key="citizen-man_13", phase="citizen", event="man_13", building="Beached schooner", lines={
        {"pike", "Tomas, your schooner has a fine keel and shocking manners. May I mend her?"},
        {"tomas", "Can she float again? She hasn't been wet in years."},
        {"pike", "For a bargain. I'll patch her and sell planks, and we'll split what the traders pay."},
    }},
    {key="citizen-man_14", phase="citizen", event="man_14", building="Star observatory", lines={
        {"amani", "Elena, forgive the dust. Does anyone here read these old star charts?"},
        {"elena", "Nobody. Why, can you? I'd give a week of tea for that."},
        {"amani", "Tea is fine. I'll copy one chart a night, and you'll pick the clear sky for each crossing."},
    }},
    {key="citizen-man_15", phase="citizen", event="man_15", building="Relic museum", lines={
        {"sato", "Elena, please don't touch the glass. Where did these pots come from?"},
        {"elena", "Three crates of loose pottery, all from the dig. Can you put them in order?"},
        {"sato", "Gladly. Put them on a shelf, and visitors will drop a coin for each case."},
    }},
    {key="citizen-man_16", phase="citizen", event="man_16", building="Temple of the Sun", lines={
        {"ixchel", "Mara, sit on the step, it's still warm. Who told you stones don't talk?"},
        {"mara", "Nobody, I just never listened. Tell me one, I'll pay in biscuits."},
        {"ixchel", "Come at dusk. The stories I tell will point you at the stars."},
    }},
}
